import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import "./IncomeCategory.css";
import "./Questionnaire.css";

function SpendingPriority({ updateData, formData }) {
  const navigate = useNavigate();

  const categories = [
    "Food & Groceries",
    "Shopping",
    "Bills",
    "Health",
    "Entertainment",
    "Transport"
  ];

  const [selected, setSelected] = useState({});
  const [values, setValues] = useState({});

  // initialize from formData if exists
  useEffect(() => {
    if (formData.spendingPriorities) {
      setValues(formData.spendingPriorities);
      const sel = {};
      Object.keys(formData.spendingPriorities).forEach(cat => {
        sel[cat] = true;
      });
      setSelected(sel);
    }
  }, [formData]);

  const toggleCategory = (cat) => {
    setSelected(prev => {
      const newSelected = { ...prev, [cat]: !prev[cat] };
      if (newSelected[cat] && !values[cat]) {
        setValues(prevValues => ({ ...prevValues, [cat]: 3 }));
      }
      return newSelected;
    });
  };

  const handleSlider = (cat, val) => {
    setValues(prev => ({ ...prev, [cat]: Number(val) }));
  };

  const handleContinue = () => {
    const filtered = categories.filter(cat => selected[cat] && values[cat] >= 3);

    if (filtered.length === 0) {
      alert("No categories selected with priority ≥ 3");
      return;
    }

    updateData({ spendingPriorities: values }); // save to formData
    navigate("/budget");
  };

  return (
    <div className="income-container">
      <h1 className="income-title">Set Your Spending Priorities</h1>
      <p className="income-subtitle">
        Select categories and assign priority (0–5)
      </p>

      <div className="income-grid">
        {categories.map(cat => (
          <div
            key={cat}
            className="income-card"
            onClick={() => toggleCategory(cat)}
            style={{ border: selected[cat] ? "2px solid #1e3c72" : "1px solid #dcdcdc" }}
          >
            <div className="income-name">{cat}</div>
            {selected[cat] && (
              <div style={{ marginTop: "15px" }}>
                <input
                  type="range"
                  min="0"
                  max="5"
                  value={values[cat] ?? 3}
                  onChange={(e) => handleSlider(cat, e.target.value)}
                  style={{ width: "100%" }}
                />
                <div style={{ textAlign: "center", marginTop: "5px" }}>
                  Priority: {values[cat] ?? 3}
                </div>
              </div>
            )}
          </div>
        ))}
      </div>

      <button
        className="next-button"
        style={{ maxWidth: "300px" }}
        onClick={handleContinue}
      >
        Continue
      </button>
    </div>
  );
}

export default SpendingPriority;
